input.script:
() => { 
  const cb = document.querySelector('input[type="checkbox"][aria-label]'); 
  if (cb) { 
    const rect = cb.getBoundingClientRect();
    const event = new MouseEvent('click', {
      bubbles: true,
      cancelable: true,
      view: window,
      clientX: rect.left + rect.width/2,
      clientY: rect.top + rect.height/2
    });
    cb.dispatchEvent(event);
    return 'dispatched click at ' + rect.left + ',' + rect.top + ' size:' + rect.width + 'x' + rect.height;
  } 
  return 'no checkbox found';
}

() => { 
  const iframes = document.querySelectorAll('iframe');
  const results = [];
  iframes.forEach((f, i) => {
    results.push({index: i, src: f.src, id: f.id, name: f.name});
  });
  const cb = document.querySelector('input[type="checkbox"]');
  return JSON.stringify({
    iframes: results,
    cb_exists: !!cb,
    cb_html: cb ? cb.outerHTML : null,
    title: document.title
  });
}
